// 三角形递归法彭罗斯镶嵌
//
// Triangular Recursive Penrose Tiling Method

// https://tilings.math.uni-bielefeld.de/substitution/robinson-triangle/

// https://www.shadertoy.com/view/MX3BzH


#define L(b) abs(cross(u-c,b).z)//                 
#define B(e) ( cross(a-d,e-d) * cross(u-d,e-d) ).z > 0. ?//

void mainImage(out vec4 o, vec2 U)
{
        vec3 u ,  a, b, c, d, e;              
        u.xy = U / iResolution.x;
        float G = .618, T,i=0.;      

        o *= i;

        b.x = 5., a = -b;  // triangle a b c

        for( c.y = 3.6 ; i++<10.; )                     
                if(T<.5)
                        d = a + (b - a) * G,
                        e = a + (c - a) * G,                                                      
                          B(e)       b=a, a=d, c=e
                        : B(c)  T++, a=e, b=c, c=d
                        :          ( a=b, b=c, c=d );
                else
                        d = c + (a - c) * G,                                               
                          B(b)       c=b, b=a, a=d
                        :     ( T--, a=b, b=c, c=d );                        
        //o.g = ++T*.3;
        //o = max(o, 1.2-2e3*min(L(a-c), L(b-c)));// 388ch   orginal:1.-1e3* 
        //o = max(vec4(0,++T*.3,0,0), 2e-4/min(L(a-c), L(b-c))); // 385ch
        //o = o*0. + max(++T*.3, 1.-2e3*min(L(a-c), L(b-c)));    // 380
        //o = o*0. + max(++T*.3, 9e-5/min(L(a-c), L(b-c)));      // 378     

        float l = length(a-c), h = abs(.5-length(u-a)/l);

        o =o*0.-smoothstep( 6. , 0.,
              1e2 * min(
                      L(a - c),
                      L(b - c)
                  )/l/l); 



        //a.x = cos(h*50.);
        //a.y = mix(h,a.x,T);
        a.y=mix(h,a.x=cos(h*50.),T);

        o.yw += .6 * smoothstep(.1, 0.,a.xy);

        //o.x += (1.-T)*.8;
        o.x += .8-T*.8;

        o = mix(o,o.xwzw, smoothstep(.4, .8, u.x));

}




